function getUtcFromLocal(dateStr, timeStr, timeZone) {
  const [yyyy, mm, dd] = dateStr.split('-').map(Number);
  const [hh, min] = timeStr.split(':').map(Number);
  const utcDate = new Date(Date.UTC(yyyy, mm - 1, dd, hh, min, 0));
  const invDate = new Date(utcDate.toLocaleString('en-US', { timeZone: 'UTC' }));
  const targetDate = new Date(utcDate.toLocaleString('en-US', { timeZone: timeZone }));
  const diff = targetDate.getTime() - invDate.getTime();
  return new Date(utcDate.getTime() - diff);
}

function formatInTimezone(dateObj, timeZone, options) {
  return new Intl.DateTimeFormat('en-US', { timeZone, ...options }).format(dateObj);
}

function getLocalWeekday(dateStr, timeStr, timeZone) {
  const d = getUtcFromLocal(dateStr, timeStr || '12:00', timeZone);
  const dayStr = new Intl.DateTimeFormat('en-US', { timeZone, weekday: 'short' }).format(d);
  const map = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };
  return map[dayStr];
}

const items = $input.all().map(i => i.json).filter(j => j.appointment_id && j.reminder_tier && j.status === 'CONFIRMED');

const results = [];
for (const appt of items) {
  const tz = appt.timezone || 'Asia/Kolkata';
  const startDt = new Date(appt.start_time);
  const dateStr = formatInTimezone(startDt, tz, { month: 'short', day: 'numeric', year: 'numeric' });
  const timeStr = formatInTimezone(startDt, tz, { hour: '2-digit', minute: '2-digit' });

  let timeNotice = '';
  if (appt.reminder_tier === '3D') timeNotice = 'in 3 days';
  else if (appt.reminder_tier === '1D') timeNotice = 'tomorrow';
  else if (appt.reminder_tier === '4H') timeNotice = 'in 4 hours';
  else if (appt.reminder_tier === '1H') timeNotice = 'in 1 hour';

  const body = `🔔 *APPOINTMENT REMINDER*\n\n` +
  `Hello ${appt.customer_name}, this is a reminder for your upcoming visit ${timeNotice}.\n\n` +
  `📋 *Reference:* #${appt.appointment_id}\n` +
  `👨‍⚕️ *Doctor:* ${appt.doctor_name || appt.doctor_id}\n` +
  `💼 *Service:* ${appt.service}\n` +
  `📅 *Date:* ${dateStr}\n` +
  `⏰ *Time:* ${timeStr} (${tz})\n\n` +
  `📍 *Location:* Apex Healthcare Clinic, Main Facility\n\n` +
  `If you need to reschedule or cancel, please reply directly to this message.`;

  results.push({
    json: {
      ...appt,
      reminder_body: body
    }
  });
}

return results;
